    -- 4) segment ~۲ متری
    v_snap_pt := ST_ClosestPoint(v_boundary, v_click_pt);

    v_loc := ST_LineLocatePoint(v_boundary, v_snap_pt);
    v_len := ST_Length(v_boundary);

    IF v_len <= 0 THEN
