        )
    WHERE d.id = p_door_id;

    -- 8) بازسازی door_access_points
    DELETE FROM door_access_points dap WHERE dap.door_id = p_door_id;

    INSERT INTO door_access_points (
        door_id,
        geom,
        floor,
        from_area,
        to_area
    )
    VALUES (
        p_door_id,
        v_dap_geom,
        v_door_floor,
        v_area_id,
        v_neighbor_area
    )
    RETURNING id, geom
    INTO dap_id, dap_geom;

    -- 9) خروجی یک ردیف
    door_id        := p_door_id;
