DECLARE
  v_origin_node bigint;
  v_dest_node   bigint;

  v_status  text;
  v_details jsonb;

  v_sql_base text;
  v_sql_pen  text;

  v_i int;
  v_mult float8;

  v_has_path boolean;
BEGIN
  --------------------------------------------------------------------
  -- 1) نزدیک‌ترین نود به مبدأ
  --------------------------------------------------------------------
  SELECT n.id
  INTO v_origin_node
  FROM routing_nodes n
  WHERE n.floor = p_floor
  ORDER BY n.geom <-> p_origin
  LIMIT 1;

  IF v_origin_node IS NULL THEN
    v_status  := 'NO_ORIGIN_NODE';
    v_details := jsonb_build_object('msg','هیچ نود مسیریابی نزدیک به مبدأ پیدا نشد','floor',p_floor);
    PERFORM fn_log_route_debug('pgr_penalized', p_mode, p_gender, p_floor, p_origin, p_dest,
                              NULL, NULL, NULL, v_status, v_details);
    RETURN;
  END IF;

  --------------------------------------------------------------------
  -- 2) نزدیک‌ترین نود به مقصد
  --------------------------------------------------------------------
  SELECT n.id
  INTO v_dest_node
  FROM routing_nodes n
  WHERE n.floor = p_floor
  ORDER BY n.geom <-> p_dest
  LIMIT 1;

  IF v_dest_node IS NULL THEN
    v_status  := 'NO_DEST_NODE';
    v_details := jsonb_build_object('msg','هیچ نود مسیریابی نزدیک به مقصد پیدا نشد','floor',p_floor);
    PERFORM fn_log_route_debug('pgr_penalized', p_mode, p_gender, p_floor, p_origin, p_dest,
                              v_origin_node, NULL, NULL, v_status, v_details);
    RETURN;
  END IF;

  --------------------------------------------------------------------
  -- 3) ساخت جدول یال‌ها با id واقعی (کلیدی‌ترین اصلاح!)
  --------------------------------------------------------------------
  DROP TABLE IF EXISTS tmp_edges_live;
  CREATE TEMP TABLE tmp_edges_live AS
  SELECT
    e.id::bigint              AS id,
    e.src::bigint             AS source,
    e.dst::bigint             AS target,
    e.cost::float8            AS cost,
    e.reverse_cost::float8            AS reverse_cost,
		e.geom::geometry(LineString, 32640) AS geom
  FROM fn_routing_edges_live_param(
    p_now,
    p_gender,
    p_mode,
    p_floor
  ) e;
	
	  --------------------------------------------------------------------
  -- 3-bis) حذف یال‌هایی که داخل areas غیرفعال هستند
  --------------------------------------------------------------------
  -- فرض: جدول پایه edges = routing_edges (id, floor, geom, ...)
  -- اگر اسم / ساختار فرق دارد، فقط این بخش را با نام واقعی تطبیق بده.
--   DELETE FROM tmp_edges_live tel
--   USING routing_edges_static re
--   LEFT JOIN areas a
--     ON a.floor = p_floor
--    AND ST_Intersects(a.geom, re.geom)
--   WHERE
--     re.id = tel.id
--     AND a.id IS NOT NULL
--     AND (
--          a.is_closed = true
--          OR (a.attrs->'operational'->>'status') IN ('inactive', 'closed')
--     );
-- 

-- DELETE FROM tmp_edges_live tel
-- USING areas a
-- WHERE
--   a.floor = p_floor
--   AND ST_Intersects(a.geom, tel.geom)
--   AND (
--         a.is_closed = true
--         OR (a.attrs->'operational'->>'status') IN ('inactive', 'closed')
--       );


  IF NOT EXISTS (SELECT 1 FROM tmp_edges_live) THEN
    v_status  := 'NO_EDGES';
    v_details := jsonb_build_object('msg','هیچ یال فعالی برای این floor/mode پیدا نشد','floor',p_floor,'mode',p_mode);
    PERFORM fn_log_route_debug('pgr_penalized', p_mode, p_gender, p_floor, p_origin, p_dest,
                              v_origin_node, v_dest_node, NULL, v_status, v_details);
    RETURN;
  END IF;

  v_sql_base := 'SELECT id, source, target, cost, reverse_cost FROM tmp_edges_live';

  --------------------------------------------------------------------
  -- 4) جدول پنالتی یال‌ها (مجموع یال‌های مسیرهای انتخاب‌شده)
  --------------------------------------------------------------------
  DROP TABLE IF EXISTS tmp_pen_edges;
  CREATE TEMP TABLE tmp_pen_edges (
    edge_id bigint PRIMARY KEY
  );

  --------------------------------------------------------------------
  -- 5) جدول خروجی مسیرها
  --------------------------------------------------------------------
  DROP TABLE IF EXISTS tmp_paths_out;
  CREATE TEMP TABLE tmp_paths_out (
    path_rank int,
    line_geom geometry(LineString,32640),
    line_cost numeric
  );

  --------------------------------------------------------------------
  -- تابع کمکی داخلی: از خروجی pgr یک LineString بساز
  --------------------------------------------------------------------
  -- مسیر 1..k را تکرار می‌کنیم: هر بار shortest path با پنالتی‌های جدید
  --------------------------------------------------------------------
  v_i := 1;
  WHILE v_i <= LEAST(GREATEST(p_k,1), 10) LOOP

    -- ضریب پنالتی: مسیر اصلی بدون پنالتی، بعدی‌ها شدیدتر
    IF v_i = 1 THEN
      v_mult := 1.0;
      v_sql_pen := v_sql_base;
    ELSE
      -- هرچه i بزرگ‌تر، پنالتی بیشتر → اختلاف مسیر بیشتر
      v_mult := 1.0 + (v_i - 1) * 1.75;  -- 2.75, 4.5, 6.25, ...
      v_sql_pen := format(
        'SELECT id, source, target,
                CASE WHEN id IN (SELECT edge_id FROM tmp_pen_edges) THEN cost * %s ELSE cost END AS cost,
                CASE WHEN id IN (SELECT edge_id FROM tmp_pen_edges) THEN reverse_cost * %s ELSE reverse_cost END AS reverse_cost
         FROM tmp_edges_live',
        v_mult, v_mult
      );
    END IF;

    ----------------------------------------------------------------
    -- 5-1) اجرای shortest path (dijkstra) با SQL فعلی
    ----------------------------------------------------------------
    DROP TABLE IF EXISTS tmp_route_raw;
    CREATE TEMP TABLE tmp_route_raw AS
    SELECT *
    FROM pgr_dijkstra(
      v_sql_pen,
      v_origin_node,
      v_dest_node,
      directed := true
    );

    v_has_path := EXISTS (SELECT 1 FROM tmp_route_raw);

    IF NOT v_has_path THEN
      -- برای i=1 یعنی اصلاً مسیر نیست، برای بقیه یعنی alternative تمام شد
      IF v_i = 1 THEN
        v_status  := 'NO_PATH';
        v_details := jsonb_build_object(
          'msg','هیچ مسیر گرافی پیدا نشد (pgr_dijkstra)',
          'origin_node', v_origin_node,
          'dest_node', v_dest_node
        );
        PERFORM fn_log_route_debug('pgr_penalized', p_mode, p_gender, p_floor, p_origin, p_dest,
                                  v_origin_node, v_dest_node, NULL, v_status, v_details);
      END IF;
      EXIT;
    END IF;

    ----------------------------------------------------------------
    -- 5-2) اضافه کردن یال‌های این مسیر به لیست پنالتی (برای دفعه بعد)
    ----------------------------------------------------------------
    INSERT INTO tmp_pen_edges(edge_id)
    SELECT DISTINCT r.edge::bigint
    FROM tmp_route_raw r
    WHERE r.edge <> -1
    ON CONFLICT DO NOTHING;

    ----------------------------------------------------------------
    -- 5-3) ساخت LineString از nodeها
    ----------------------------------------------------------------
    DROP TABLE IF EXISTS tmp_route_nodes;
    CREATE TEMP TABLE tmp_route_nodes AS
    SELECT
      r.seq       AS rn_seq,
      r.node      AS rn_node,
      r.agg_cost  AS rn_agg_cost,
      n.geom      AS rn_geom
    FROM tmp_route_raw r
    JOIN routing_nodes n
      ON n.id = r.node
    ORDER BY r.seq;

    DROP TABLE IF EXISTS tmp_route_line;
    CREATE TEMP TABLE tmp_route_line AS
    SELECT
      ST_MakeLine(rn_geom ORDER BY rn_seq)::geometry(LineString,32640) AS line_geom,
      max(rn_agg_cost)::numeric                                         AS line_cost
    FROM tmp_route_nodes;

    ----------------------------------------------------------------
    -- 5-4) ذخیره خروجی این مسیر
    ----------------------------------------------------------------
    INSERT INTO tmp_paths_out(path_rank, line_geom, line_cost)
    SELECT v_i, line_geom, line_cost
    FROM tmp_route_line;

    v_i := v_i + 1;
  END LOOP;

  --------------------------------------------------------------------
  -- 6) خروجی نهایی
  --------------------------------------------------------------------
  RETURN QUERY
  SELECT o.path_rank, o.line_geom AS geom, o.line_cost AS cost
  FROM tmp_paths_out o
  ORDER BY o.path_rank;

END;

