        );
        PERFORM fn_log_route_debug('pgr_penalized', p_mode, p_gender, p_floor, p_origin, p_dest,
                                  v_origin_node, v_dest_node, NULL, v_status, v_details);
      END IF;
      EXIT;
    END IF;

    ----------------------------------------------------------------
    -- 5-2) اضافه کردن یال‌های این مسیر به لیست پنالتی (برای دفعه بعد)
    ----------------------------------------------------------------
    INSERT INTO tmp_pen_edges(edge_id)
    SELECT DISTINCT r.edge::bigint
    FROM tmp_route_raw r
    WHERE r.edge <> -1
    ON CONFLICT DO NOTHING;

    ----------------------------------------------------------------
    -- 5-3) ساخت LineString از nodeها
    ----------------------------------------------------------------
    DROP TABLE IF EXISTS tmp_route_nodes;
    CREATE TEMP TABLE tmp_route_nodes AS
    SELECT
      r.seq       AS rn_seq,
      r.node      AS rn_node,
      r.agg_cost  AS rn_agg_cost,
      n.geom      AS rn_geom
    FROM tmp_route_raw r
    JOIN routing_nodes n
      ON n.id = r.node
    ORDER BY r.seq;

    DROP TABLE IF EXISTS tmp_route_line;
    CREATE TEMP TABLE tmp_route_line AS
    SELECT
      ST_MakeLine(rn_geom ORDER BY rn_seq)::geometry(LineString,32640) AS line_geom,
      max(rn_agg_cost)::numeric                                         AS line_cost
    FROM tmp_route_nodes;

    ----------------------------------------------------------------
    -- 5-4) ذخیره خروجی این مسیر
    ----------------------------------------------------------------
    INSERT INTO tmp_paths_out(path_rank, line_geom, line_cost)
    SELECT v_i, line_geom, line_cost
    FROM tmp_route_line;

    v_i := v_i + 1;
  END LOOP;

  --------------------------------------------------------------------
  -- 6) خروجی نهایی
  --------------------------------------------------------------------
  RETURN QUERY
  SELECT o.path_rank, o.line_geom AS geom, o.line_cost AS cost
  FROM tmp_paths_out o
  ORDER BY o.path_rank;

END;
$function$

